import type { FinancialBeneficiary, SecurityNotification, Transaction, User, Wallet, WalletRecipient } from './services/api'

type Action = 'wallet' | 'my-qr' | 'transfer' | 'withdrawal' | 'deposit' | null
type ScannerError = { message: string } | null
type Notice = { type: 'error' | 'success'; text: string } | null
type NotificationItem = { id: string; transaction?: Transaction; title: string; message: string; icon: string; tone: 'in' | 'out' | 'neutral'; createdAt?: string }
type TransferFeedback = { type: 'success' | 'error'; title: string; message: string; reference?: string } | null
type DepositFeedback = { amount: string; currency: string; reference: string; balance: string | number } | null

const amountPattern = /^(?:0|[1-9]\d{0,15})(?:\.\d{1,2})?$/
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const navItems = [
  ['Overview', 'grid'], ['Accounts', 'wallet'], ['Payments', 'send'],
  ['Cards', 'card'], ['Transactions', 'list'], ['Insights', 'chart'], ['Settings', 'settings'],
] as const

