function money(value: number, currency: string) {
  try { return new Intl.NumberFormat('en-PK', { style: 'currency', currency, minimumFractionDigits: 2 }).format(value) }
  catch { return `${currency} ${value.toFixed(2)}` }
}

function dateTime(value?: string) {
  if (!value) return '—'
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('en-PK', { dateStyle: 'medium', timeStyle: 'short' }).format(date)
}

export function greetingForHour(hour: number) {
  if (hour >= 5 && hour < 12) return 'Good morning'
  if (hour >= 12 && hour < 18) return 'Good afternoon'
  return 'Good evening'
}

function escapeReceiptHtml(value: string) {
  return value.replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character] ?? character)
}

function relativeTime(value?: string) {
  if (!value) return 'Recently'
  const time = new Date(value).getTime()
  if (Number.isNaN(time)) return 'Recently'
  const seconds = Math.max(0, Math.floor((Date.now() - time) / 1000))
  if (seconds < 60) return 'Just now'
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`
  const days = Math.floor(hours / 24)
  if (days < 7) return `${days} day${days === 1 ? '' : 's'} ago`
  return dateTime(value)
}

function flowOf(transaction: Transaction, wallet?: Wallet) {
  return transaction.senderWalletId === wallet?.id ? 'out' : 'in'
}

function maskEmail(email: string) {
  const [name, domain] = email.split('@')
  return `${(name || '').slice(0, 2)}•••@${domain || ''}`
}

function Brand() { return <div className="ov-brand"><span>N</span><strong>NOVA <i>BANK</i></strong></div> }

function EmptyTransactions() {
  return <div className="ov-empty"><span><DashIcon name="receipt" /></span><h3>No transactions yet</h3><p>Your transfers, withdrawals, and incoming payments will appear here.</p></div>
}

function TransactionRows({ transactions, wallet, onSelect }: { transactions: Transaction[]; wallet?: Wallet; onSelect: (item: Transaction) => void }) {
  if (!transactions.length) return <EmptyTransactions />
  return <div className="ov-transactions">{transactions.map(item => { const flow = flowOf(item, wallet); const currency = item.currency || wallet?.currency || 'PKR'; return <button type="button" onClick={() => onSelect(item)} className="ov-transaction" key={item.id}><span className={`ov-transaction-icon ${flow}`}><DashIcon name={flow === 'in' ? 'arrowDown' : 'arrowUp'} /></span><span className="ov-transaction-copy"><strong>{item.type.replaceAll('_', ' ')}</strong><small>{item.description || item.reference}</small><time>{dateTime(item.createdAt)}</time></span><span className="ov-reference">{item.reference}</span><span className={`ov-status ${item.status.toLowerCase()}`}>{item.status}</span><span className={`ov-amount ${flow}`}>{flow === 'out' ? '−' : '+'}{money(Number(item.amount), currency)}</span></button> })}</div>
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="ov-modal-layer" onMouseDown={onClose}><section className="ov-modal" role="dialog" aria-modal="true" aria-labelledby="ov-modal-title" onMouseDown={event => event.stopPropagation()}><header><div><small>NOVA BANK</small><h2 id="ov-modal-title">{title}</h2></div><button type="button" onClick={onClose} aria-label="Close"><DashIcon name="close" /></button></header>{children}</section></div>
}

function QrScanner({ onDetected, onClose, onError }: { onDetected: (walletId: string) => void; onClose: () => void; onError: (message: string) => void }) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    let stream: MediaStream | undefined
    let frame = 0
    let active = true
    async function start() {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } }, audio: false })
        if (!active || !videoRef.current) { stream.getTracks().forEach(track => track.stop()); return }
        videoRef.current.srcObject = stream
        await videoRef.current.play()
        const scan = () => {
          const video = videoRef.current; const canvas = canvasRef.current
          if (!active || !video || !canvas) return
          if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA && video.videoWidth && video.videoHeight) {
            const width = Math.min(video.videoWidth, 720); const height = Math.round(width * video.videoHeight / video.videoWidth)
            canvas.width = width; canvas.height = height
            const context = canvas.getContext('2d', { willReadFrequently: true })
            context?.drawImage(video, 0, 0, width, height)
            const image = context?.getImageData(0, 0, width, height)
            const code = image ? jsQR(image.data, width, height, { inversionAttempts: 'dontInvert' }) : null
            if (code?.data) { active = false; stream?.getTracks().forEach(track => track.stop()); onDetected(code.data.trim()); return }
          }
          frame = window.requestAnimationFrame(scan)
        }
        frame = window.requestAnimationFrame(scan)
      } catch (error) {
        const denied = error instanceof DOMException && (error.name === 'NotAllowedError' || error.name === 'SecurityError')
        onError(denied ? 'Camera permission is required to scan a QR code.' : 'Camera is unavailable on this device.')
      }
    }
    void start()
    return () => { active = false; window.cancelAnimationFrame(frame); stream?.getTracks().forEach(track => track.stop()) }
  }, [onDetected, onError])
  return <div className="qr-scanner-layer" role="dialog" aria-modal="true" aria-label="Scan Nova Bank QR"><section className="qr-scanner"><header><button type="button" onClick={onClose} aria-label="Close scanner"><DashIcon name="close" /></button><div><small>NOVA BANK</small><h2>Scan Nova Bank QR</h2></div><span /></header><div className="qr-camera"><video ref={videoRef} playsInline muted /><canvas ref={canvasRef} hidden /><div className="qr-scan-frame"><i /><i /><i /><i /></div></div><h3>Scan Nova Bank QR</h3><p>Point your camera at the recipient's QR code.</p></section></div>
}

export default function Dashboard({ user, onLogout }: { user: User; onLogout: () => void }) {
  const [wallets, setWallets] = useState<Wallet[]>([]); const [transactions, setTransactions] = useState<Transaction[]>([])
  const [securityNotifications, setSecurityNotifications] = useState<SecurityNotification[]>([])
  const [notificationError, setNotificationError] = useState(false)
  const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [notice, setNotice] = useState<Notice>(null)
  const [balanceVisible, setBalanceVisible] = useState(true); const [sidebarOpen, setSidebarOpen] = useState(false); const [action, setAction] = useState<Action>(null); const [submitting, setSubmitting] = useState(false)
  const [recipient, setRecipient] = useState<WalletRecipient | null>(null); const [recipientLoading, setRecipientLoading] = useState(false); const [recipientError, setRecipientError] = useState(''); const [transferConfirm, setTransferConfirm] = useState(false)
  const [transferFeedback, setTransferFeedback] = useState<TransferFeedback>(null); const [deposit, setDeposit] = useState({ amount: '', idempotencyKey: '' }); const [depositError, setDepositError] = useState(''); const [depositFeedback, setDepositFeedback] = useState<DepositFeedback>(null); const [fundingSources, setFundingSources] = useState<FinancialBeneficiary[]>([]); const [withdrawalBeneficiaries, setWithdrawalBeneficiaries] = useState<FinancialBeneficiary[]>([]); const [selectedFundingSource, setSelectedFundingSource] = useState(''); const [selectedWithdrawalBeneficiary, setSelectedWithdrawalBeneficiary] = useState(''); const [beneficiaryLoading, setBeneficiaryLoading] = useState(false); const [beneficiaryForm, setBeneficiaryForm] = useState({ label: '', identifier: '' }); const [beneficiaryError, setBeneficiaryError] = useState(''); const [depositReview, setDepositReview] = useState(false); const [withdrawalReview, setWithdrawalReview] = useState(false); const [withdrawalFeedback, setWithdrawalFeedback] = useState<DepositFeedback>(null)
  const [scannerOpen, setScannerOpen] = useState(false); const [scannerKey, setScannerKey] = useState(0); const [scannerError, setScannerError] = useState<ScannerError>(null); const [myQr, setMyQr] = useState<string>('')
  const [selected, setSelected] = useState<Transaction | null>(null); const [detailLoading, setDetailLoading] = useState(false)
  const [profileOpen, setProfileOpen] = useState(false); const [profilePanel, setProfilePanel] = useState<'profile' | 'security' | 'settings' | null>(null); const [activeNav, setActiveNav] = useState('Overview'); const [moduleInfo, setModuleInfo] = useState<{ title: string; message: string } | null>(null); const [localHour, setLocalHour] = useState(() => new Date().getHours()); const profileRef = useRef<HTMLDivElement>(null)
  const [notificationsOpen, setNotificationsOpen] = useState(false); const notificationsRef = useRef<HTMLDivElement>(null)
  const notificationStorageKey = `nova-notifications-read:${user.id}`
  const [readNotificationIds, setReadNotificationIds] = useState<string[]>(() => { try { const stored = localStorage.getItem(notificationStorageKey); return stored ? JSON.parse(stored) as string[] : [] } catch { return [] } })
  const [transfer, setTransfer] = useState({ receiverWalletId: '', amount: '', description: '' }); const [withdrawal, setWithdrawal] = useState({ amount: '', description: '', idempotencyKey: '' })
  const wallet = wallets[0]; const balance = Number(wallet?.balance || 0); const currency = wallet?.currency || 'PKR'
  const canShareWalletQr = 'share' in navigator
  const canShareReceipt = 'share' in navigator
  const amountValue = Number(transfer.amount)
  const amountError = transfer.amount.length === 0 ? '' : !amountPattern.test(transfer.amount.trim()) || amountValue <= 0 ? 'Enter an amount greater than zero.' : amountValue > balance ? `Insufficient balance. Available: ${money(balance, currency)}.` : ''

  const loadData = useCallback(async (quiet = false) => { if (quiet) setRefreshing(true); else setLoading(true); const [walletResult, transactionResult, securityResult] = await Promise.allSettled([bankingApi.walletBalance(), bankingApi.transactions(1, 100), notificationApi.security()]); if (walletResult.status === 'fulfilled' && transactionResult.status === 'fulfilled') { setWallets(walletResult.value.wallets); setTransactions(transactionResult.value.transactions); setNotice(null) } else { setNotice({ type: 'error', text: 'Unable to load your account information.' }) } if (securityResult.status === 'fulfilled') { setSecurityNotifications(securityResult.value.securityNotifications); setNotificationError(false) } else { setSecurityNotifications([]); setNotificationError(true) } setLoading(false); setRefreshing(false) }, [])
  useEffect(() => { const initialLoad = window.setTimeout(() => void loadData(), 0); return () => window.clearTimeout(initialLoad) }, [loadData])
  useEffect(() => { const timer = window.setInterval(() => setLocalHour(new Date().getHours()), 60_000); return () => window.clearInterval(timer) }, [])
  useEffect(() => {
    if (!profileOpen && !profilePanel && !notificationsOpen) return
    function closeOnOutside(event: PointerEvent) { const target = event.target as Node; if (profileOpen && profileRef.current && !profileRef.current.contains(target)) setProfileOpen(false); if (notificationsOpen && notificationsRef.current && !notificationsRef.current.contains(target)) setNotificationsOpen(false) }
    function closeOnEscape(event: KeyboardEvent) { if (event.key === 'Escape') { setProfileOpen(false); setProfilePanel(null); setNotificationsOpen(false) } }
    document.addEventListener('pointerdown', closeOnOutside)
    document.addEventListener('keydown', closeOnEscape)
    if (profileOpen) window.requestAnimationFrame(() => profileRef.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus())
    if (notificationsOpen) window.requestAnimationFrame(() => notificationsRef.current?.querySelector<HTMLButtonElement>('.notification-row')?.focus())
    return () => { document.removeEventListener('pointerdown', closeOnOutside); document.removeEventListener('keydown', closeOnEscape) }
  }, [profileOpen, profilePanel, notificationsOpen])
  useEffect(() => { try { localStorage.setItem(notificationStorageKey, JSON.stringify(readNotificationIds)) } catch { /* Local read state remains available for this session. */ } }, [notificationStorageKey, readNotificationIds])

  const summary = useMemo(() => { const today = new Date(); const completed = transactions.filter(item => { const date = item.createdAt ? new Date(item.createdAt) : null; return item.status === 'COMPLETED' && date && date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear() }); const incoming = completed.filter(item => flowOf(item, wallet) === 'in').reduce((total, item) => total + Number(item.amount), 0); const outgoing = completed.filter(item => flowOf(item, wallet) === 'out').reduce((total, item) => total + Number(item.amount), 0); return { incoming, outgoing, net: incoming - outgoing } }, [transactions, wallet])
  const notificationItems = useMemo<NotificationItem[]>(() => {
    const transactionItems: NotificationItem[] = transactions.filter(item => item.status === 'COMPLETED' && ['TRANSFER', 'WITHDRAWAL', 'DEPOSIT'].includes(item.type)).map(item => { const flow = flowOf(item, wallet); const itemCurrency = item.currency || currency; if (item.type === 'WITHDRAWAL') return { id: item.id, transaction: item, title: 'Withdrawal completed', message: `${money(Number(item.amount), itemCurrency)} withdrawn`, icon: 'arrowUp', tone: 'out', createdAt: item.completedAt || item.createdAt }; if (item.type === 'DEPOSIT') return { id: item.id, transaction: item, title: 'Deposit completed', message: `${money(Number(item.amount), itemCurrency)} deposited`, icon: 'plus', tone: 'in', createdAt: item.completedAt || item.createdAt }; return { id: item.id, transaction: item, title: flow === 'in' ? 'Money received' : 'Transfer successful', message: `${money(Number(item.amount), itemCurrency)} ${flow === 'in' ? 'received' : 'sent'}`, icon: flow === 'in' ? 'arrowDown' : 'send', tone: flow, createdAt: item.completedAt || item.createdAt } })
    const securityItems = securityNotifications.map(item => ({ id: `security:${item.id}`, title: item.title, message: `${item.message} ${item.authMethod}.`, icon: 'shield', tone: 'neutral' as const, createdAt: item.createdAt }))
    return [...transactionItems, ...securityItems].sort((left, right) => new Date(right.createdAt || 0).getTime() - new Date(left.createdAt || 0).getTime())
  }, [transactions, securityNotifications, wallet, currency])
  const unreadCount = notificationItems.reduce((count, item) => count + (readNotificationIds.includes(item.id) ? 0 : 1), 0)

  useEffect(() => { if (!wallet?.id || action !== 'my-qr') return; let active = true; void QRCode.toDataURL(wallet.id, { width: 260, margin: 2, color: { dark: '#251d68', light: '#ffffff' }, errorCorrectionLevel: 'M' }).then(value => { if (active) setMyQr(value) }).catch(() => { if (active) setMyQr('') }); return () => { active = false } }, [wallet?.id, action])

  function validAmount(value: string) { return amountPattern.test(value.trim()) && Number(value) > 0 && Number(value) <= balance }
  function depositAmountMessage(value: string) { const amount = value.trim(); if (!amount) return 'Enter a deposit amount.'; if (amount.startsWith('-')) return 'Amount must be greater than zero.'; if (!amountPattern.test(amount)) return /^\d+\.\d{3,}$/.test(amount) ? 'Amount may have no more than 2 decimal places.' : 'Enter a valid positive amount.'; if (Number(amount) === 0) return 'Amount must be greater than zero.'; return '' }
  function openTransfer() { setTransfer({ receiverWalletId: '', amount: '', description: '' }); setRecipient(null); setRecipientError(''); setTransferConfirm(false); setTransferFeedback(null); setAction('transfer') }
  async function loadBeneficiaries(kind: FinancialBeneficiary['kind']) { setBeneficiaryLoading(true); setBeneficiaryError(''); try { const result = await bankingApi.beneficiaries(kind); if (kind === 'FUNDING_SOURCE') setFundingSources(result.beneficiaries); else setWithdrawalBeneficiaries(result.beneficiaries) } catch (error) { setBeneficiaryError(error instanceof Error ? error.message : 'Unable to load beneficiaries.') } finally { setBeneficiaryLoading(false) } }
  function openDeposit() { setDeposit({ amount: '', idempotencyKey: crypto.randomUUID() }); setDepositError(''); setDepositFeedback(null); setSelectedFundingSource(''); setDepositReview(false); setAction('deposit'); void loadBeneficiaries('FUNDING_SOURCE') }
  function openWithdrawal() { setWithdrawal({ amount: '', description: '', idempotencyKey: crypto.randomUUID() }); setSelectedWithdrawalBeneficiary(''); setWithdrawalReview(false); setBeneficiaryError(''); setAction('withdrawal'); void loadBeneficiaries('WITHDRAWAL_DESTINATION') }
  async function addBeneficiary(kind: FinancialBeneficiary['kind']) { if (!beneficiaryForm.label.trim() || !beneficiaryForm.identifier.trim()) { setBeneficiaryError('Enter a name and test account identifier.'); return } setBeneficiaryLoading(true); setBeneficiaryError(''); try { const result = await bankingApi.addBeneficiary(kind, beneficiaryForm.label, beneficiaryForm.identifier); if (kind === 'FUNDING_SOURCE') { setFundingSources(current => [result.beneficiary, ...current]); setSelectedFundingSource(result.beneficiary.id) } else { setWithdrawalBeneficiaries(current => [result.beneficiary, ...current]); setSelectedWithdrawalBeneficiary(result.beneficiary.id) } setBeneficiaryForm({ label: '', identifier: '' }) } catch (error) { setBeneficiaryError(error instanceof Error ? error.message : 'Unable to add beneficiary.') } finally { setBeneficiaryLoading(false) } }
  async function removeBeneficiary(kind: FinancialBeneficiary['kind'], id: string) { if (!id) return; setBeneficiaryLoading(true); setBeneficiaryError(''); try { await bankingApi.deactivateBeneficiary(id); if (kind === 'FUNDING_SOURCE') { setFundingSources(current => current.filter(item => item.id !== id)); setSelectedFundingSource('') } else { setWithdrawalBeneficiaries(current => current.filter(item => item.id !== id)); setSelectedWithdrawalBeneficiary('') } } catch (error) { setBeneficiaryError(error instanceof Error ? error.message : 'Unable to remove beneficiary.') } finally { setBeneficiaryLoading(false) } }
  const openScanner = useCallback(() => { setProfileOpen(false); setNotificationsOpen(false); setScannerError(null); setScannerKey(value => value + 1); setScannerOpen(true) }, [])
  const scannerFailed = useCallback((message: string) => { setScannerOpen(false); setScannerError({ message }) }, [])
  const scannedWallet = useCallback(async (payload: string) => { setScannerOpen(false); if (!uuidPattern.test(payload)) { setScannerError({ message: 'This is not a valid Nova Bank wallet QR code.' }); return } if (payload === wallet?.id) { setScannerError({ message: 'You cannot send money to your own wallet.' }); return } setRecipientLoading(true); try { const result = await bankingApi.recipient(payload); if (result.recipient.status !== 'ACTIVE') { setScannerError({ message: 'Recipient wallet is not active.' }); return } if (result.recipient.currency !== currency) { setScannerError({ message: `This wallet cannot receive ${currency} payments.` }); return } setTransfer({ receiverWalletId: payload, amount: '', description: '' }); setRecipient(result.recipient); setRecipientError(''); setTransferConfirm(false); setTransferFeedback(null); setAction('transfer') } catch { setScannerError({ message: 'Recipient wallet could not be found.' }) } finally { setRecipientLoading(false) } }, [wallet?.id, currency])
  async function pasteRecipientId() { try { const value = (await navigator.clipboard.readText()).trim(); setTransfer(current => ({ ...current, receiverWalletId: value })); setRecipientError(uuidPattern.test(value) ? '' : 'The pasted value is not a valid wallet ID.') } catch { setTransferFeedback({ type: 'error', title: 'Paste unavailable', message: 'Allow clipboard access or enter the wallet ID manually.' }) } }
  async function lookupRecipient(event: FormEvent) { event.preventDefault(); const walletId = transfer.receiverWalletId.trim(); setRecipient(null); if (!uuidPattern.test(walletId)) { setRecipientError('Enter a valid recipient wallet ID.'); return } if (walletId === wallet?.id) { setRecipientError('You cannot send money to your own wallet.'); return } setRecipientLoading(true); setRecipientError(''); try { const result = await bankingApi.recipient(walletId); if (result.recipient.status !== 'ACTIVE') { setRecipientError('This recipient wallet is not active.'); return } if (result.recipient.currency !== currency) { setRecipientError(`This wallet cannot receive ${currency} transfers.`); return } setRecipient(result.recipient) } catch (error) { setRecipientError(error instanceof Error ? error.message : 'Recipient could not be found.') } finally { setRecipientLoading(false) } }
  function reviewTransfer(event: FormEvent) { event.preventDefault(); if (!wallet || !recipient || !validAmount(transfer.amount)) { setRecipientError('Enter an amount within your available balance.'); return } setRecipientError(''); setTransferConfirm(true) }
  async function confirmTransfer() { if (!wallet || !recipient || submitting) return; const sentAmount = transfer.amount.trim(); setSubmitting(true); try { const result = await bankingApi.transfer(wallet.id, recipient.walletId, sentAmount, transfer.description.trim()); setTransfer({ receiverWalletId: '', amount: '', description: '' }); setRecipient(null); setTransferConfirm(false); setAction(null); await loadData(true); setTransferFeedback({ type: 'success', title: 'Payment Successful', message: `${money(Number(sentAmount), currency)} sent successfully.`, reference: result.transaction.reference }) } catch (error) { const message = error instanceof Error ? error.message : 'Transfer could not be completed.'; const friendlyMessage = /insufficient/i.test(message) ? `Insufficient balance. Your available balance is ${money(balance, currency)}.` : /not found|recipient/i.test(message) ? 'The recipient wallet could not be found.' : /belong|unauthor|not allowed/i.test(message) ? 'You are not authorized to use this wallet.' : /connect|reach|network/i.test(message) ? 'Unable to connect to Nova Bank. Check your connection and try again.' : /temporarily unavailable|complete transfer/i.test(message) ? 'Transfer service is temporarily unavailable. Please try again.' : message; setTransferConfirm(false); setTransferFeedback({ type: 'error', title: 'Transfer unsuccessful', message: friendlyMessage }) } finally { setSubmitting(false) } }
  async function copyWalletId() { if (!wallet) return; try { await navigator.clipboard.writeText(wallet.id); setNotice({ type: 'success', text: 'Wallet ID copied.' }) } catch { setNotice({ type: 'error', text: 'Wallet ID could not be copied.' }) } }
  async function shareWalletQr() { if (!wallet || !canShareWalletQr) return; try { await navigator.share({ title: 'Nova Bank — Receive Money', text: `Nova Bank wallet ID: ${wallet.id}` }) } catch (error) { if (error instanceof DOMException && error.name === 'AbortError') return; setNotice({ type: 'error', text: 'Wallet ID could not be shared.' }) } }
  function receiptText(transaction: Transaction) { const transactionCurrency = transaction.currency || currency; return `Nova Bank transaction receipt\nReference: ${transaction.reference}\nAmount: ${money(Number(transaction.amount), transactionCurrency)}\nType: ${transaction.type.replaceAll('_', ' ')}\nSender: ${transaction.senderWalletId || '—'}\nReceiver: ${transaction.receiverWalletId || '—'}\nDate/time: ${dateTime(transaction.completedAt || transaction.createdAt)}\nStatus: ${transaction.status}` }
  function downloadReceipt(transaction: Transaction) { const transactionCurrency = transaction.currency || currency; const rows = [['Transaction reference', transaction.reference], ['Amount', money(Number(transaction.amount), transactionCurrency)], ['Currency', transactionCurrency], ['Transaction type', transaction.type.replaceAll('_', ' ')], ['Sender wallet', transaction.senderWalletId || '—'], ['Receiver wallet', transaction.receiverWalletId || '—'], ['Date/time', dateTime(transaction.completedAt || transaction.createdAt)], ['Status', transaction.status], ['Description', transaction.description || '—']].map(([label, value]) => `<tr><th>${escapeReceiptHtml(label)}</th><td>${escapeReceiptHtml(value)}</td></tr>`).join(''); const receipt = `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Nova Bank Receipt ${escapeReceiptHtml(transaction.reference)}</title><style>body{margin:0;background:#f5f7fb;color:#202738;font:14px Arial,sans-serif}.receipt{max-width:680px;margin:32px auto;padding:36px;background:#fff;border-radius:16px;box-shadow:0 8px 30px #1d23401a}.brand{color:#594bd7;font-weight:800;letter-spacing:.08em}.brand span{color:#697486}.tag{display:inline-block;margin:20px 0 10px;padding:6px 10px;border-radius:99px;color:#18745a;background:#e7f8f1;font-size:12px;font-weight:700}h1{margin:0;font-size:28px}p{color:#697486}table{width:100%;margin-top:25px;border-collapse:collapse}th,td{padding:13px 0;border-bottom:1px solid #e8ebf0;text-align:left;vertical-align:top}th{width:42%;color:#697486;font-weight:600}td{overflow-wrap:anywhere;font-weight:700}.footer{margin-top:28px;color:#697486;font-size:12px}@media print{body{background:#fff}.receipt{margin:0;box-shadow:none}}</style></head><body><main class="receipt"><div class="brand">NOVA <span>BANK</span></div><span class="tag">${escapeReceiptHtml(transaction.status)}</span><h1>Transaction Receipt</h1><p>Keep this receipt for your records.</p><table>${rows}</table><p class="footer">Generated by Nova Bank from your authenticated transaction record.</p></main></body></html>`; const blob = new Blob([receipt], { type: 'text/html;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `nova-bank-receipt-${transaction.reference}.html`; document.body.append(link); link.click(); link.remove(); URL.revokeObjectURL(url) }
  async function shareReceipt(transaction: Transaction) { if (!canShareReceipt) return; try { await navigator.share({ title: `Nova Bank receipt ${transaction.reference}`, text: receiptText(transaction) }) } catch (error) { if (error instanceof DOMException && error.name === 'AbortError') return; setNotice({ type: 'error', text: 'Receipt could not be shared.' }) } }
  function reviewDeposit(event: FormEvent) { event.preventDefault(); const message = depositAmountMessage(deposit.amount); if (!selectedFundingSource) { setDepositError('Select or add a test funding source.'); return } if (message) { setDepositError(message); return } setDepositError(''); setDepositReview(true) }
  async function submitDeposit() { if (!wallet || !selectedFundingSource || submitting) return; const amount = deposit.amount.trim(); setSubmitting(true); setDepositError(''); try { const result = await bankingApi.deposit(wallet.id, selectedFundingSource, amount, deposit.idempotencyKey); setAction(null); setDepositReview(false); await loadData(true); setDepositFeedback({ amount: String(result.transaction.amount), currency: result.wallet.currency, reference: result.transaction.reference, balance: result.wallet.balance }) } catch (error) { setDepositReview(false); setDepositError(error instanceof Error ? error.message : 'Deposit could not be completed.') } finally { setSubmitting(false) } }
  function reviewWithdrawal(event: FormEvent) { event.preventDefault(); if (!selectedWithdrawalBeneficiary) { setBeneficiaryError('Select or add a withdrawal beneficiary.'); return } if (!validAmount(withdrawal.amount)) { setBeneficiaryError(withdrawal.amount.startsWith('-') ? 'Amount must be greater than zero.' : 'Enter an amount within your available balance with no more than 2 decimal places.'); return } setBeneficiaryError(''); setWithdrawalReview(true) }
  async function submitWithdrawal() { if (!wallet || !selectedWithdrawalBeneficiary || submitting) return; setSubmitting(true); try { const result = await bankingApi.withdrawal(wallet.id, selectedWithdrawalBeneficiary, withdrawal.amount.trim(), withdrawal.description.trim(), withdrawal.idempotencyKey); setAction(null); setWithdrawalReview(false); await loadData(true); setWithdrawalFeedback({ amount: String(result.transaction.amount), currency: result.wallet.currency, reference: result.transaction.reference, balance: result.wallet.balance }) } catch (error) { setWithdrawalReview(false); setBeneficiaryError(error instanceof Error ? error.message : 'Withdrawal could not be completed.') } finally { setSubmitting(false) } }
  async function showDetails(item: Transaction) { setSelected(item); setDetailLoading(true); try { const result = await bankingApi.transactionDetails(item.id); setSelected(result.transaction) } catch { setSelected(null); setNotice({ type: 'error', text: 'Transaction details could not be loaded.' }) } finally { setDetailLoading(false) } }
  function navClick(label: string) { setSidebarOpen(false); setActiveNav(label); if (label === 'Overview') return; if (label === 'Accounts') { setAction('wallet'); return } if (label === 'Payments') { openTransfer(); return } if (label === 'Transactions') { document.querySelector('.overview-recent')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return } if (label === 'Settings') { setProfilePanel('settings'); return } const message = label === 'Cards' ? 'Cards are not enabled for this account.' : 'Insights are not enabled for this account.'; setModuleInfo({ title: label, message }) }
  function openProfilePanel(panel: 'profile' | 'security' | 'settings') { setProfileOpen(false); setProfilePanel(panel) }
  function logoutFromProfile() { setProfileOpen(false); onLogout() }
  function markNotificationRead(id: string) { setReadNotificationIds(current => current.includes(id) ? current : [...current, id]) }
  function markAllNotificationsRead() { setReadNotificationIds(current => Array.from(new Set([...current, ...notificationItems.map(item => item.id)]))) }
  function openNotification(item: NotificationItem) { markNotificationRead(item.id); setNotificationsOpen(false); if (item.transaction) void showDetails(item.transaction) }

  const greetingName = user.email.split('@')[0] || 'customer'
  return <div className="overview-shell">
    <aside className={`overview-sidebar ${sidebarOpen ? 'open' : ''}`}><Brand /><nav aria-label="Main navigation">{navItems.map(([label, icon]) => <button type="button" className={activeNav === label ? 'active' : ''} onClick={() => navClick(label)} key={label}><DashIcon name={icon} /><span>{label}</span>{activeNav === label && <i />}</button>)}</nav><button type="button" className="overview-logout" onClick={onLogout}><DashIcon name="logout" /> Log out</button></aside>
    {sidebarOpen && <button className="overview-scrim" type="button" aria-label="Close navigation" onClick={() => setSidebarOpen(false)} />}
    <main className="overview-main"><header className="overview-header"><div className="overview-title"><button className="overview-menu" type="button" onClick={() => setSidebarOpen(true)} aria-label="Open navigation">☰</button><div><small>PERSONAL BANKING</small><h1>Overview</h1><p>{greetingForHour(localHour)}, {greetingName}</p></div></div><div className="overview-header-actions"><div className="notifications-wrap" ref={notificationsRef}><button className="overview-bell" type="button" onClick={() => { setNotificationsOpen(value => !value); setProfileOpen(false) }} aria-label={`Notifications${unreadCount ? `, ${unreadCount} unread` : ''}`} aria-haspopup="dialog" aria-expanded={notificationsOpen}><DashIcon name="bell" />{unreadCount > 0 && <span className="notification-badge">{unreadCount > 9 ? '9+' : unreadCount}</span>}</button><button className="overview-scan" type="button" onClick={openScanner} aria-label="Scan QR" title="Scan QR"><DashIcon name="scan" /></button>{notificationsOpen && <section className="notifications-panel" role="dialog" aria-label="Notifications"><header><div><small>ACCOUNT ACTIVITY</small><h2>Notifications</h2></div><button type="button" onClick={() => setNotificationsOpen(false)} aria-label="Close notifications"><DashIcon name="close" /></button></header>{notificationItems.length ? <><div className="notifications-list">{notificationItems.map(item => { const unread = !readNotificationIds.includes(item.id); return <button type="button" className={`notification-row ${unread ? 'unread' : ''}`} onClick={() => openNotification(item)} key={item.id}><i className={item.tone}><DashIcon name={item.icon} /></i><span><strong>{item.title}</strong><small>{item.message}</small><time>{relativeTime(item.createdAt)}</time></span>{unread && <b aria-label="Unread" />}</button> })}</div><footer><button type="button" onClick={markAllNotificationsRead} disabled={!unreadCount}>Mark all as read</button></footer></> : <div className="notifications-empty"><span><DashIcon name="bell" /></span><h3>{notificationError ? 'Notifications unavailable' : 'No notifications yet'}</h3><p>{notificationError ? 'Your account is available. Notifications could not be loaded right now.' : 'Completed account activity will appear here.'}</p></div>}</section>}</div><div className="overview-profile-wrap" ref={profileRef}><button className="overview-profile" type="button" onClick={() => { setProfileOpen(value => !value); setNotificationsOpen(false) }} aria-haspopup="menu" aria-expanded={profileOpen}><span className="overview-avatar">{user.email.charAt(0).toUpperCase()}</span><span><strong>{greetingName}</strong><small>{maskEmail(user.email)}</small></span><DashIcon name="down" /></button>{profileOpen && <div className="profile-menu" role="menu"><header><span className="overview-avatar">{user.email.charAt(0).toUpperCase()}</span><div><strong>{greetingName}</strong><small>{user.email}</small>{user.phone && <small>{user.phone}</small>}</div></header><div className="profile-menu-group"><button role="menuitem" type="button" onClick={() => openProfilePanel('profile')}><i><DashIcon name="user" /></i><span><strong>Profile</strong><small>View account information</small></span></button><button role="menuitem" type="button" onClick={() => openProfilePanel('security')}><i><DashIcon name="shield" /></i><span><strong>Security</strong><small>Authentication overview</small></span></button><button role="menuitem" type="button" onClick={() => openProfilePanel('settings')}><i><DashIcon name="settings" /></i><span><strong>Settings</strong><small>Preferences and controls</small></span></button></div><button className="profile-menu-logout" role="menuitem" type="button" onClick={logoutFromProfile}><DashIcon name="logout" /> Log out</button></div>}</div></div></header>
      <div className="overview-content" aria-busy={loading || refreshing}>{notice && <div className={`overview-notice ${notice.type}`} role="status">{notice.text}<button onClick={() => setNotice(null)}>×</button></div>}{loading ? <div className="overview-loading"><span className="spinner" /><h2>Loading your account...</h2><p>Securely retrieving your latest balance and activity.</p></div> : <>
        <section className="overview-hero-grid"><article className="overview-balance"><div className="overview-balance-top"><span>Available Balance</span><button type="button" onClick={() => setBalanceVisible(value => !value)} aria-label={balanceVisible ? 'Hide balance' : 'Show balance'}><DashIcon name={balanceVisible ? 'eye' : 'eyeOff'} /></button></div><strong>{balanceVisible ? money(balance, currency) : `${currency} ••••••`}</strong><div><span>{currency} Wallet</span><i className={wallet?.status.toLowerCase()}>{wallet?.status || 'Unavailable'}</i></div><span className="balance-ring" /></article><section className="overview-summary"><header><div><small>THIS MONTH</small><h2>Money summary</h2></div><button type="button" onClick={() => void loadData(true)} disabled={refreshing} aria-label="Refresh account data"><DashIcon name="refresh" /></button></header><div><span><i className="in"><DashIcon name="arrowDown" /></i><small>Incoming</small><strong>{money(summary.incoming, currency)}</strong></span><span><i className="out"><DashIcon name="arrowUp" /></i><small>Outgoing</small><strong>{money(summary.outgoing, currency)}</strong></span><span><i className={summary.net >= 0 ? 'in' : 'out'}>∑</i><small>Net</small><strong>{money(summary.net, currency)}</strong></span></div></section></section>
        <section className="overview-actions"><div className="overview-section-title"><div><small>EVERYDAY BANKING</small><h2>Quick actions</h2></div></div><div><button type="button" onClick={() => setAction('wallet')}><i className="purple"><DashIcon name="wallet" /></i><span><strong>My Wallet</strong><small>View and copy wallet ID</small></span><b>›</b></button><button type="button" onClick={openTransfer}><i className="purple"><DashIcon name="send" /></i><span><strong>Send Money</strong><small>Transfer to another wallet</small></span><b>›</b></button><button type="button" onClick={openWithdrawal}><i className="blue"><DashIcon name="arrowUp" /></i><span><strong>Withdraw</strong><small>Move money from wallet</small></span><b>›</b></button><button type="button" onClick={openDeposit}><i className="green"><DashIcon name="plus" /></i><span><strong>Deposit</strong><small>Add funds to your account</small></span><b>›</b></button></div></section>
        <section className="overview-recent"><div className="overview-section-title"><div><small>LATEST ACTIVITY</small><h2>Recent Transactions</h2></div><span>{transactions.length} total</span></div><TransactionRows transactions={transactions.slice(0, 6)} wallet={wallet} onSelect={item => void showDetails(item)} /></section>
      </>}</div>
      <nav className="overview-mobile-nav" aria-label="Mobile navigation"><button type="button" className={activeNav === 'Overview' ? 'active' : ''} onClick={() => navClick('Overview')}><DashIcon name="grid" /><span>Overview</span></button><button type="button" className={activeNav === 'Accounts' ? 'active' : ''} onClick={() => navClick('Accounts')}><DashIcon name="wallet" /><span>Accounts</span></button><button type="button" className="mobile-scan" onClick={openScanner} aria-label="Scan QR"><i><DashIcon name="scan" /></i><span>Scan</span></button><button type="button" className={activeNav === 'Payments' ? 'active' : ''} onClick={() => navClick('Payments')}><DashIcon name="send" /><span>Payments</span></button><button type="button" className={activeNav === 'Cards' ? 'active' : ''} onClick={() => navClick('Cards')}><DashIcon name="card" /><span>Cards</span></button></nav>
    </main>
    {action === 'wallet' && <Modal title="My Wallet" onClose={() => setAction(null)}><div className="wallet-identity"><span className="wallet-identity-icon"><DashIcon name="wallet" /></span><div><small>NOVA BANK</small><strong>My Wallet</strong><i>{currency} · {wallet?.status || 'Unavailable'}</i></div><dl><div><dt>Wallet ID</dt><dd>{wallet?.id || 'Unavailable'}</dd></div><div><dt>Currency</dt><dd>{currency}</dd></div><div><dt>Balance</dt><dd>{money(balance, currency)}</dd></div></dl><div className="wallet-identity-actions wallet-actions"><button type="button" onClick={() => setAction('my-qr')} disabled={!wallet}><DashIcon name="scan" /> My QR</button><button type="button" onClick={() => void copyWalletId()} disabled={!wallet}><DashIcon name="copy" /> Copy Wallet ID</button><button type="button" onClick={() => setAction(null)}>Close</button></div></div></Modal>}
    {action === 'my-qr' && <Modal title="My QR" onClose={() => setAction(null)}><div className="wallet-identity receive-money-qr"><span className="wallet-identity-icon"><DashIcon name="wallet" /></span><div><small>NOVA BANK</small><strong>Receive Money</strong><i>Scan to pay this wallet</i></div><div className="my-wallet-qr">{myQr ? <img src={myQr} alt="QR code containing only your Nova Bank wallet ID" /> : <span className="spinner" />}</div><dl><div><dt>Wallet ID</dt><dd>{wallet?.id || 'Unavailable'}</dd></div></dl><div className={`wallet-identity-actions${canShareWalletQr ? ' has-share' : ''}`}><button type="button" onClick={() => void copyWalletId()} disabled={!wallet}><DashIcon name="copy" /> Copy Wallet ID</button>{canShareWalletQr && <button type="button" onClick={() => void shareWalletQr()} disabled={!wallet}>Share QR</button>}<button type="button" onClick={() => setAction(null)}>Close</button></div></div></Modal>}
    {action === 'transfer' && !transferConfirm && !transferFeedback && <Modal title="Send Money" onClose={() => setAction(null)}><div className="transfer-steps"><span className={recipient ? 'complete' : 'active'}>1 <small>Recipient</small></span><span className={recipient ? 'active' : ''}>2 <small>Amount</small></span><span>3 <small>Review</small></span></div>{!recipient ? <form className="ov-action-form recipient-form" onSubmit={lookupRecipient}><label>Recipient Wallet ID<div className="wallet-id-control"><input value={transfer.receiverWalletId} onChange={event => { setTransfer({ ...transfer, receiverWalletId: event.target.value.trim() }); setRecipientError('') }} placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx" required disabled={recipientLoading} autoComplete="off" aria-invalid={Boolean(recipientError)} /><button type="button" onClick={() => void pasteRecipientId()} disabled={recipientLoading}><DashIcon name="copy" /> Paste</button></div></label><p className="field-hint">Paste the UUID shared from the recipient’s My Wallet screen.</p>{recipientError && <p className="transfer-error" role="alert">{recipientError}</p>}<button disabled={recipientLoading || !wallet || !uuidPattern.test(transfer.receiverWalletId)}>{recipientLoading ? <><span className="spinner" /> Checking recipient…</> : 'Continue'}</button></form> : <form className="ov-action-form amount-form" onSubmit={reviewTransfer}><div className="recipient-preview"><i><DashIcon name="user" /></i><span><small>RECIPIENT CONFIRMED</small><strong>{recipient.identifier}</strong><em><b>{recipient.currency}</b> wallet <b>{recipient.status}</b></em></span><button type="button" onClick={() => { setRecipient(null); setRecipientError('') }}>Change</button></div><label>Amount<div className="transfer-amount-input"><span>{currency}</span><input type="number" min="0.01" step="0.01" value={transfer.amount} onChange={event => { setTransfer({ ...transfer, amount: event.target.value }); setRecipientError('') }} placeholder="0.00" required aria-invalid={Boolean(amountError)} /></div></label><div className="amount-balance"><span>Available balance</span><strong>{money(balance, currency)}</strong></div>{amountError && <p className="transfer-error" role="alert">{amountError}</p>}<label>Description <span>Optional</span><textarea maxLength={500} value={transfer.description} onChange={event => setTransfer({ ...transfer, description: event.target.value })} placeholder="Add a note for this transfer" /></label>{recipientError && <p className="transfer-error" role="alert">{recipientError}</p>}<button disabled={!validAmount(transfer.amount)}>Review Transfer</button></form>}</Modal>}
    {action === 'transfer' && transferConfirm && recipient && !transferFeedback && <Modal title="Review Transfer" onClose={() => setTransferConfirm(false)}><div className="transfer-confirm"><span><DashIcon name="send" /></span><small>TRANSFER REVIEW</small><strong>{money(Number(transfer.amount), currency)}</strong><div className="review-recipient"><i><DashIcon name="user" /></i><span><small>RECIPIENT</small><strong>{recipient.walletId}</strong><em>{recipient.identifier}</em></span></div><dl><div><dt>Amount</dt><dd>{money(Number(transfer.amount), currency)}</dd></div><div><dt>Currency</dt><dd>{currency}</dd></div>{transfer.description && <div><dt>Description</dt><dd>{transfer.description}</dd></div>}</dl><div><button type="button" onClick={() => setTransferConfirm(false)} disabled={submitting}>Back</button><button type="button" onClick={() => void confirmTransfer()} disabled={submitting}>{submitting ? <><span className="spinner" /> Sending securely…</> : 'Confirm Transfer'}</button></div></div></Modal>}
    {transferFeedback && <Modal title={transferFeedback.title} onClose={() => setTransferFeedback(null)}><div className={`transfer-feedback ${transferFeedback.type}`}><span><DashIcon name={transferFeedback.type === 'success' ? 'shield' : 'close'} /></span><h3>{transferFeedback.title}</h3><p>{transferFeedback.message}</p>{transferFeedback.reference && <div><small>TRANSACTION REFERENCE</small><strong>{transferFeedback.reference}</strong></div>}<button type="button" onClick={() => setTransferFeedback(null)}>{transferFeedback.type === 'success' ? 'Done' : 'Try Again'}</button></div></Modal>}
    {moduleInfo && <Modal title={moduleInfo.title} onClose={() => setModuleInfo(null)}><div className="settings-soon"><span><DashIcon name={moduleInfo.title === 'Cards' ? 'card' : 'chart'} /></span><h3>{moduleInfo.title} unavailable</h3><p>{moduleInfo.message}</p><button type="button" onClick={() => { setModuleInfo(null); setActiveNav('Overview') }}>Back to Overview</button></div></Modal>}
    {scannerOpen && <QrScanner key={scannerKey} onDetected={payload => void scannedWallet(payload)} onClose={() => setScannerOpen(false)} onError={scannerFailed} />}
    {scannerError && <Modal title="QR Scanner" onClose={() => setScannerError(null)}><div className="scanner-error"><span><DashIcon name="scan" /></span><h3>Unable to scan</h3><p>{scannerError.message}</p><div><button type="button" onClick={() => setScannerError(null)}>Close</button><button type="button" onClick={openScanner}>Try Again</button></div></div></Modal>}
    {action === 'withdrawal' && !withdrawalReview && <Modal title="Withdraw" onClose={() => setAction(null)}><form className="ov-action-form" onSubmit={reviewWithdrawal}><div className="deposit-wallet-summary"><span>Source wallet</span><strong>{wallet?.id || '—'}</strong><span>Available balance</span><strong>{money(balance, currency)}</strong><span>Currency</span><strong>{currency}</strong></div><label>Withdrawal beneficiary<select value={selectedWithdrawalBeneficiary} onChange={event => setSelectedWithdrawalBeneficiary(event.target.value)} disabled={beneficiaryLoading || submitting}><option value="">Select destination</option>{withdrawalBeneficiaries.map(item => <option value={item.id} key={item.id}>{item.label} · {item.maskedIdentifier}</option>)}</select></label>{selectedWithdrawalBeneficiary && <button className="beneficiary-remove" type="button" onClick={() => void removeBeneficiary('WITHDRAWAL_DESTINATION', selectedWithdrawalBeneficiary)} disabled={beneficiaryLoading}>Remove selected destination</button>}<div className="beneficiary-add"><small>Development/test destination only — no real provider is connected.</small><input value={beneficiaryForm.label} onChange={event => setBeneficiaryForm({ ...beneficiaryForm, label: event.target.value })} placeholder="Beneficiary name" disabled={beneficiaryLoading} /><input value={beneficiaryForm.identifier} onChange={event => setBeneficiaryForm({ ...beneficiaryForm, identifier: event.target.value })} placeholder="Test account identifier" disabled={beneficiaryLoading} /><button type="button" onClick={() => void addBeneficiary('WITHDRAWAL_DESTINATION')} disabled={beneficiaryLoading}>Add destination</button></div><label>Amount ({currency})<input type="text" inputMode="decimal" value={withdrawal.amount} onChange={event => setWithdrawal({ ...withdrawal, amount: event.target.value })} placeholder="0.00" required disabled={submitting} /></label><label>Description <span>Optional</span><textarea maxLength={500} value={withdrawal.description} onChange={event => setWithdrawal({ ...withdrawal, description: event.target.value })} placeholder="Withdrawal note" disabled={submitting} /></label>{beneficiaryError && <p className="transfer-error" role="alert">{beneficiaryError}</p>}<div className="deposit-actions"><button type="button" onClick={() => setAction(null)} disabled={submitting}>Cancel</button><button disabled={submitting || !wallet || beneficiaryLoading}>Review Withdrawal</button></div></form></Modal>}
    {action === 'withdrawal' && withdrawalReview && <Modal title="Review Withdrawal" onClose={() => !submitting && setWithdrawalReview(false)}><div className="transfer-confirm"><span><DashIcon name="arrowUp" /></span><small>WITHDRAWAL REVIEW</small><strong>{money(Number(withdrawal.amount), currency)}</strong><dl><div><dt>Destination</dt><dd>{withdrawalBeneficiaries.find(item => item.id === selectedWithdrawalBeneficiary)?.label} · {withdrawalBeneficiaries.find(item => item.id === selectedWithdrawalBeneficiary)?.maskedIdentifier}</dd></div><div><dt>Fee</dt><dd>{money(0, currency)}</dd></div><div><dt>Final amount</dt><dd>{money(Number(withdrawal.amount), currency)}</dd></div></dl><div><button type="button" onClick={() => setWithdrawalReview(false)} disabled={submitting}>Back</button><button type="button" onClick={() => void submitWithdrawal()} disabled={submitting}>{submitting ? 'Processing…' : 'Confirm Withdrawal'}</button></div></div></Modal>}
    {action === 'deposit' && !depositReview && <Modal title="Deposit" onClose={() => !submitting && setAction(null)}><form className="ov-action-form" onSubmit={reviewDeposit}><div className="deposit-wallet-summary"><span>Destination wallet</span><strong>{wallet?.id || '—'}</strong><span>Current balance</span><strong>{money(balance, currency)}</strong><span>Currency</span><strong>{currency}</strong></div><label>Funding source<select value={selectedFundingSource} onChange={event => setSelectedFundingSource(event.target.value)} disabled={beneficiaryLoading || submitting}><option value="">Select test funding source</option>{fundingSources.map(item => <option value={item.id} key={item.id}>{item.label} · {item.maskedIdentifier}</option>)}</select></label>{selectedFundingSource && <button className="beneficiary-remove" type="button" onClick={() => void removeBeneficiary('FUNDING_SOURCE', selectedFundingSource)} disabled={beneficiaryLoading}>Remove selected funding source</button>}<div className="beneficiary-add"><small>Development/test funding source only — no real provider is connected.</small><input value={beneficiaryForm.label} onChange={event => setBeneficiaryForm({ ...beneficiaryForm, label: event.target.value })} placeholder="Funding source name" disabled={beneficiaryLoading} /><input value={beneficiaryForm.identifier} onChange={event => setBeneficiaryForm({ ...beneficiaryForm, identifier: event.target.value })} placeholder="Test account identifier" disabled={beneficiaryLoading} /><button type="button" onClick={() => void addBeneficiary('FUNDING_SOURCE')} disabled={beneficiaryLoading}>Add funding source</button></div><label>Amount ({currency})<input type="text" inputMode="decimal" value={deposit.amount} onChange={event => { setDeposit({ ...deposit, amount: event.target.value }); setDepositError('') }} placeholder="0.00" required disabled={submitting} aria-invalid={Boolean(depositError)} /></label>{depositError && <p className="transfer-error" role="alert">{depositError}</p>}<div className="deposit-actions"><button type="button" onClick={() => setAction(null)} disabled={submitting}>Cancel</button><button type="submit" disabled={submitting || !wallet || beneficiaryLoading}>Review Deposit</button></div></form></Modal>}
    {action === 'deposit' && depositReview && <Modal title="Review Deposit" onClose={() => !submitting && setDepositReview(false)}><div className="transfer-confirm"><span><DashIcon name="plus" /></span><small>DEPOSIT REVIEW</small><strong>{money(Number(deposit.amount), currency)}</strong><dl><div><dt>Funding source</dt><dd>{fundingSources.find(item => item.id === selectedFundingSource)?.label} · {fundingSources.find(item => item.id === selectedFundingSource)?.maskedIdentifier}</dd></div><div><dt>Fee</dt><dd>{money(0, currency)}</dd></div><div><dt>Final credited amount</dt><dd>{money(Number(deposit.amount), currency)}</dd></div></dl><div><button type="button" onClick={() => setDepositReview(false)} disabled={submitting}>Back</button><button type="button" onClick={() => void submitDeposit()} disabled={submitting}>{submitting ? 'Processing…' : 'Confirm Deposit'}</button></div></div></Modal>}
    {depositFeedback && <Modal title="Deposit Successful" onClose={() => setDepositFeedback(null)}><div className="transfer-feedback success"><span><DashIcon name="shield" /></span><h3>Deposit completed</h3><p>{money(Number(depositFeedback.amount), depositFeedback.currency)} has been deposited.</p><div className="deposit-success-summary"><span>Currency<strong>{depositFeedback.currency}</strong></span><span>Transaction reference<strong>{depositFeedback.reference}</strong></span><span>New wallet balance<strong>{money(Number(depositFeedback.balance), depositFeedback.currency)}</strong></span></div><button type="button" onClick={() => setDepositFeedback(null)}>Done</button></div></Modal>}
    {withdrawalFeedback && <Modal title="Withdrawal Successful" onClose={() => setWithdrawalFeedback(null)}><div className="transfer-feedback success"><span><DashIcon name="shield" /></span><h3>Withdrawal completed</h3><p>{money(Number(withdrawalFeedback.amount), withdrawalFeedback.currency)} has been sent to your selected destination.</p><div className="deposit-success-summary"><span>Currency<strong>{withdrawalFeedback.currency}</strong></span><span>Transaction reference<strong>{withdrawalFeedback.reference}</strong></span><span>New wallet balance<strong>{money(Number(withdrawalFeedback.balance), withdrawalFeedback.currency)}</strong></span></div><button type="button" onClick={() => setWithdrawalFeedback(null)}>Done</button></div></Modal>}
    {selected && <Modal title="Transaction Details" onClose={() => setSelected(null)}>{detailLoading ? <div className="overview-loading compact"><span className="spinner" /><p>Loading transaction details...</p></div> : <div className="ov-detail"><div className="ov-detail-amount"><span className={`ov-transaction-icon ${flowOf(selected, wallet)}`}><DashIcon name={flowOf(selected, wallet) === 'in' ? 'arrowDown' : 'arrowUp'} /></span><strong>{money(Number(selected.amount), selected.currency || currency)}</strong><i className={`ov-status ${selected.status.toLowerCase()}`}>{selected.status}</i></div><dl><div><dt>Reference</dt><dd>{selected.reference}</dd></div><div><dt>Type</dt><dd>{selected.type.replaceAll('_', ' ')}</dd></div><div><dt>Currency</dt><dd>{selected.currency || currency}</dd></div><div><dt>Description</dt><dd>{selected.description || '—'}</dd></div><div><dt>Sender wallet</dt><dd>{selected.senderWalletId || '—'}</dd></div><div><dt>Receiver wallet</dt><dd>{selected.receiverWalletId || '—'}</dd></div><div><dt>Created</dt><dd>{dateTime(selected.createdAt)}</dd></div><div><dt>Completed</dt><dd>{dateTime(selected.completedAt)}</dd></div></dl><div className={`receipt-actions${canShareReceipt ? ' has-share' : ''}`}><button type="button" onClick={() => downloadReceipt(selected)}><DashIcon name="receipt" /> Download Receipt</button>{canShareReceipt && <button type="button" onClick={() => void shareReceipt(selected)}>Share Receipt</button>}</div></div>}</Modal>}
    {profilePanel === 'profile' && <Modal title="Your Profile" onClose={() => setProfilePanel(null)}><div className="profile-panel"><div className="profile-panel-hero"><span className="overview-avatar">{user.email.charAt(0).toUpperCase()}</span><div><h3>{greetingName}</h3><p>Nova Bank customer</p></div><i>{user.status || 'ACTIVE'}</i></div><dl><div><dt>Email address</dt><dd>{user.email}</dd></div><div><dt>Phone number</dt><dd>{user.phone || 'Not available'}</dd></div><div><dt>Account status</dt><dd><span className="profile-safe-status">{user.status || 'ACTIVE'}</span></dd></div><div><dt>Verification</dt><dd>Email verified</dd></div></dl><p className="profile-view-note"><DashIcon name="shield" /> Profile information is view only.</p></div></Modal>}
    {profilePanel === 'security' && <Modal title="Security" onClose={() => setProfilePanel(null)}><div className="security-panel"><div className="security-shield"><DashIcon name="shield" /></div><h3>Your account is protected</h3><p>Nova Bank uses verified access and an authenticated session to protect your account.</p><div><span><i><DashIcon name="user" /></i><span><small>Authentication</small><strong>Signed in securely</strong></span><b>✓</b></span><span><i><DashIcon name="shield" /></i><span><small>Email verification</small><strong>Verified</strong></span><b>✓</b></span><span><i><DashIcon name="wallet" /></i><span><small>Account status</small><strong>{user.status || 'ACTIVE'}</strong></span><b>✓</b></span></div><small className="security-footnote">No passwords or session credentials are displayed here.</small></div></Modal>}
    {profilePanel === 'settings' && <Modal title="Settings" onClose={() => setProfilePanel(null)}><div className="settings-soon"><span><DashIcon name="settings" /></span><h3>Settings are not enabled</h3><p>Account preferences and controls are not enabled for this account.</p><button type="button" onClick={() => { setProfilePanel(null); setActiveNav('Overview') }}>Back to Overview</button></div></Modal>}
  </div>
}
